import json
import time

def process_payment(idempotency_key, amount):
    cache_key = f'idemp:{idempotency_key}'
    processing_value = '__idempotency_processing__'

    while True:
        if redis.set(cache_key, processing_value, nx=True, ex=120):
            receipt = stripe.Charge.create(amount=amount)
            redis.set(cache_key, json.dumps(receipt), ex=120)
            return receipt

        cached = redis.get(cache_key)
        if cached is None:
            continue
        if isinstance(cached, (bytes, bytearray)):
            cached = cached.decode('utf-8')
        if cached == processing_value:
            time.sleep(0.05)
            continue
        return json.loads(cached) if isinstance(cached, str) else cached

